// WF-50: Prepare WhatsApp message payload
// Handles multiple message types: text, interactive, template
// Field aliases: messageContent OR message OR messageBody (callers use inconsistent names)

const input = $input.first().json;

// Extract phone number
let phoneNumber = input.phoneNumber || input.phoneNumberFormatted;

// Determine message type (default to text if not specified)
const messageType = input.messageType || 'text';

// Accept messageContent OR message OR messageBody (caller naming is inconsistent)
const messageContent = input.messageContent || input.message || input.messageBody || null;

// Guard: stop gracefully if text message has empty/null body (prevents Meta API 400)
if (messageType === 'text' && (!messageContent || messageContent.trim().length === 0)) {
  return [];
}

return {
  // Phone data
  phoneNumber: phoneNumber,
  phoneNumberFormatted: input.phoneNumber,

  // Message type and content
  messageType: messageType,
  messageContent: messageContent,
  interactivePayload: input.interactivePayload || null,
  templateName: input.templateName || null,
  templateParams: input.templateParams || [],

  // Context data for logging
  userId: input.userId || null,
  inboundMessageId: input.inboundMessageId || null,
  userMessage: input.userMessage || null
};

// Process send result and prepare for logging
const prepareData = $('Prepare Payload').first().json;
const sendResult = $input.first().json;

let success = false;
let messageId = null;
let error = null;

// Check WhatsApp API response
if (sendResult.messages && sendResult.messages[0]) {
  success = true;
  messageId = sendResult.messages[0].id;
} else if (sendResult.error) {
  error = sendResult.error.message || JSON.stringify(sendResult.error);
} else {
  // Fallback for unexpected response format
  success = true;
  messageId = 'unknown';
}

return {
  // Message delivery status
  success: success,
  messageId: messageId,
  error: error,

  // Message details
  phoneNumber: prepareData.phoneNumber,
  messageType: prepareData.messageType,
  messageContent: prepareData.messageContent,

  // Context for logging
  userId: prepareData.userId,
  inboundMessageId: prepareData.inboundMessageId,
  userMessage: prepareData.userMessage,

  // Timestamp
  sentAt: new Date().toISOString()
};

const input = $input.item.json;
const interactiveType = input.interactivePayload.type; // 'flow' or 'button'

if (interactiveType === 'flow') {
  // Flow type (your existing form logic)
  return {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: input.phoneNumber,
    type: "interactive",
    interactive: {
      type: "flow",
      header: {
        type: "text",
        text: input.interactivePayload.header.text
      },
      body: {
        text: input.interactivePayload.body.text
      },
      footer: {
        text: "Tap below to continue"
      },
      action: {
        name: "flow",
        parameters: {
          flow_message_version: "3",
          // flow_token: `${input.userId}_${Date.now()}`,
          flow_token: `${Date.now()}`,
          flow_id: input.interactivePayload.flowId,
          flow_cta: input.interactivePayload.flowCta,
          flow_action: "navigate"
        }
      }
    }
  };
} else if (interactiveType === 'button') {
  // Button type (payment confirmation, etc.)
  return {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: input.phoneNumber,
    type: "interactive",
    interactive: {
      type: "button",
      body: {
        text: input.interactivePayload.body.text
      },
      action: {
        buttons: input.interactivePayload.action.buttons
      }
    }
  };
}

const input = $input.item.json;

const components = [];
if (input.templateParams && input.templateParams.length > 0) {
  components.push({
    type: 'body',
    parameters: input.templateParams.map(p => ({ type: 'text', text: String(p) }))
  });
}

return {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: input.phoneNumber,
  type: 'template',
  template: {
    name: input.templateName,
    language: { code: 'en' },
    components: components
  }
};

// Return final status to calling workflow
const result = $('Process Result').first().json;

return {
  success: result.success,
  messageId: result.messageId,
  error: result.error,
  phoneNumber: result.phoneNumber,
  sentAt: result.sentAt
};

